// Lane Init: the QuickEnrich lane of Enrich Contacts. One run per launch over the WHOLE company
// list; the lane worries about itself: it walks the list in chunks of 100 companies (the
// size this vendor's API and pacing want), asks the vendor per chunk, and hands each chunk's people
// to the writer helper. The Rootflow only orchestrates. The input item is the Rootflow's contract:
// { base, peopleTableId, companiesTableId, peopleFields, contactSourceMulti, dncDomains,
//   companies:[{recordId, domain, company, band, cap, floor}], parentExecId, clientRecId }.
const inp=$input.first().json||{};
const who='Enrich Contacts QuickEnrich lane';
if(!/^app[A-Za-z0-9]{14}$/.test(String(inp.base||''))) throw new Error(who+' was called without a valid base.');
if(!inp.peopleTableId) throw new Error(who+' was called without peopleTableId.');
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const sd=$getWorkflowStaticData('global');
sd.lane={ execId:String($execution.id), startedAt:new Date().toISOString(), chunks:0, called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', skipped:'', built:0, updated:0, heldUnchanged:0, dupes:0, noKey:0, fenced:0, emailsAppended:0, dnc:0, written:0, updatedWritten:0, writeErrors:0, writeReasons:[], coveredDomains:{}, singleSelectSource:false, companiesIn:companies.length };
const CHUNK=100;
const out=[];
for(let i=0;i<companies.length;i+=CHUNK){ out.push({ json:{ idx:out.length+1, count:Math.ceil(companies.length/CHUNK), companies:companies.slice(i,i+CHUNK) } }); }
if(!out.length) return [{ json:{ _empty:true, idx:0, count:0, companies:[] } }];
return out;

// QE Companies: the QuickEnrich provider of Enrich Contacts. QuickEnrich has no seniority or
// department filter, so it is asked for everyone (ruled 2026-09-08: insert everyone, no pressure):
// one free contact-finder call per company for the roster, then one paid email search per person
// up to the cap. One item per company out (the roster request), or {_none:true}.
const inp=$input.first().json||{};
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const out=companies.map(c=>({ json:{ domain:String(c.domain).toLowerCase(), cap:Math.max(1,Math.min(50,Number(c.cap)||20)), body:{ company_url:{ include:[String(c.domain).toLowerCase()], exclude:[] }, per_page:100, page:1 } } }));
if(!out.length) return [{ json:{ _none:true } }];
return out;

// QE Pick: the roster answers (aligned to QE Companies by index) -> one email-search request per
// person, up to the cap per company, people with an email on file first. The roster is free; the
// search costs one credit only on a hit. Everyone picked is inserted, email or not: a person the
// roster named is a person, the email is the email Rootflow's problem. Errors ride in _stats.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const reqs=$('QE Companies').all().map(i=>i.json||{});
let answers=[]; try{ answers=$('QE Roster').all(); }catch(e){}
const st={ rosterCalled:0, rosterRows:0, errors:0, noKey:0, firstError:'', failReasons:[] };
const out=[];
const na=(v)=>{ const s=String(v==null?'':v).trim(); return (s===''||s==='N/A')?'':s; };
answers.forEach((it,i)=>{
  const req=reqs[i]; if(!req||req._none) return;
  st.rosterCalled++;
  const j=it.json||{};
  if(j.error&&j.body===undefined&&j.data===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='QuickEnrich contact-finder: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const b=(j.body!==undefined)?j.body:j;
  const status=Number(j.statusCode)||200;
  if(status>=300||!b||typeof b!=='object'||!Array.isArray(b.data)){ st.errors++; const r='QuickEnrich contact-finder HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const rows=b.data.slice().sort((a,c)=>(c.has_email?1:0)-(a.has_email?1:0));
  st.rosterRows+=rows.length;
  let n=0;
  for(const p of rows){
    if(n>=req.cap) break;
    const first=na(p.first_name), last=na(p.last_name);
    if(!first) continue;
    n++;
    // The search URL carries only the parameters that have a value: an empty linkedin_url next to
    // the name + domain trio is not a documented shape.
    const q={ linkedin_url:na(p.employee_linkedin), company_url:req.domain, first_name:first, last_name:last };
    const qs=Object.keys(q).filter(k=>q[k]).map(k=>k+'='+encodeURIComponent(q[k])).join('&');
    out.push({ json:{ domain:req.domain, name:(first+' '+last).trim(), title:na(p.title), linkedin:na(p.employee_linkedin), hasEmail:!!p.has_email, hasPhone:!!p.has_phone,
      query:q, url:'https://app.quickenrich.io/api/employees/search?'+qs } });
  }
});
if(!out.length) return [{ json:{ _none:true, _stats:st } }];
out[0].json._stats=st;
return out;

// QE Parse: the email-search answers (aligned to QE Pick by index) -> people per domain in the
// shared provider contract (see GL Parse). A person whose search found nothing is still a person
// (name, title, LinkedIn from the roster), written without an email. Seniority and department are
// derived from the title by the caller's merge. Never throws.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], rosterCalled:0, rosterRows:0, noKey:0, emails:0 };
const people={};
let first={}; try{ first=$('QE Pick').first().json||{}; }catch(e){}
const rs=first._stats||{};
for(const k of ['rosterCalled','rosterRows','noKey']) st[k]=Number(rs[k])||0;
st.errors+=Number(rs.errors)||0; if(rs.firstError&&!st.firstError) st.firstError=rs.firstError; for(const r of (rs.failReasons||[])) st.failReasons.push(r);
let picks=[]; try{ picks=$('QE Pick').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('QE Email').all(); }catch(e){}
const na=(v)=>{ const s=String(v==null?'':v).trim(); return (s===''||s==='N/A')?'':s; };
answers.forEach((it,i)=>{
  const p=picks[i]; if(!p) return;
  st.called++;
  const j=it.json||{};
  let email='', phone='', sourceId='';
  if(j.error&&j.body===undefined&&j.data===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='QuickEnrich email search: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r);
  } else {
    const b=(j.body!==undefined)?j.body:j;
    const status=Number(j.statusCode)||200;
    if(status>=300||!b||typeof b!=='object'){ st.errors++; const r='QuickEnrich email search HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); }
    else { const d=(b.data&&!Array.isArray(b.data))?b.data:((Array.isArray(b.data)&&b.data[0])||{}); email=na(d.email).toLowerCase(); phone=na(d.employee_phone); if(email){ st.emails++; st.credits+=1; } }
  }
  const list=people[p.domain]||(people[p.domain]=[]);
  st.returned++;
  list.push({ source:'QuickEnrich', sourceId:sourceId, name:p.name, title:p.title, seniority:'', department:'', email:email, linkedin:p.linkedin, phone:phone });
  st.kept++;
});
let status='ok', reason='';
const attempted=st.rosterCalled+st.called;
if(st.noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the QuickEnrich nodes'; }
else if(attempted&&st.errors>=attempted&&!st.kept){ status='error'; reason=st.firstError; }
else if(!attempted){ status='skipped'; reason='nothing to ask'; }
return [{ json:{ provider:'QuickEnrich', status, reason, stats:st, people } }];

// Writer Input: this chunk's people (from QE Parse) plus the writer's contract, one item for the
// writer helper. An empty answer still goes through the writer (it costs one held read and returns
// zero), so the lane's counters stay honest and simple.
const ctx=$('Enrich Trigger').first().json||{};
const chunk=$('Chunk Loop').first().json||{};
let parsed={}; try{ parsed=$('QE Parse').first().json||{}; }catch(e){}
return [{ json:{ base:ctx.base, peopleTableId:ctx.peopleTableId, peopleFields:ctx.peopleFields||[], contactSourceMulti:ctx.contactSourceMulti===true, dncDomains:ctx.dncDomains||[], provider:'QuickEnrich', companies:chunk.companies||[], people:(parsed.people&&typeof parsed.people==='object')?parsed.people:{} } }];

// Lane Tick: adds this chunk's vendor counters (QE Parse) and writer counters (Call Writer) to the
// lane's running totals in this execution's static data (one execution, so the accumulator holds),
// then emits one unconditional tick so the loop never depends on the payload of the work.
const sd=$getWorkflowStaticData('global'); const a=sd.lane;
const n=(v)=>Number(v)||0;
let p={}; try{ p=$('QE Parse').first().json||{}; }catch(e){}
const s=p.stats||{};
a.chunks++; a.called+=n(s.called); a.returned+=n(s.returned); a.kept+=n(s.kept); a.credits+=n(s.credits); a.errors+=n(s.errors);
if(!a.firstError&&s.firstError) a.firstError=String(s.firstError).slice(0,200);
if(p.status==='skipped'&&p.reason&&p.reason!=='nothing to ask') a.skipped=String(p.reason);
if(p.status==='error'&&!a.firstError) a.firstError=String(p.reason||'').slice(0,200);
let w={}; try{ w=$('Call Writer').first().json||{}; }catch(e){}
if(w.error&&w.written===undefined){ a.writeErrors+=1; if(a.writeReasons.length<5) a.writeReasons.push('writer crashed: '+String((w.error&&w.error.message)||w.error).slice(0,160)); }
else { for(const k of ['built','updated','heldUnchanged','dupes','noKey','fenced','emailsAppended','dnc','written','updatedWritten','writeErrors']) a[k]+=n(w[k]); if(w.singleSelectSource) a.singleSelectSource=true; for(const r of (w.writeReasons||[])){ if(a.writeReasons.length<5&&a.writeReasons.indexOf(r)<0) a.writeReasons.push(r); } for(const d of (w.coveredDomains||[])) a.coveredDomains[d]=1; }
return [{ json:{ tick:true, chunk:a.chunks } }];

// Lane Log: the lane's own Hub row, keyed "<parent execution>-quickenrich", Automation
// "Enrich Contacts QuickEnrich", Client attached. Status computed: a skipped lane (no credential,
// out of credits, nothing to ask) is Succeeded with a Skipped line; vendor errors and refused
// writes count as errors; Failed only when every call failed and nothing was written.
const ctx=$('Enrich Trigger').first().json||{};
const a=$getWorkflowStaticData('global').lane||{};
const n=(v)=>Number(v)||0;
const covered=Object.keys(a.coveredDomains||{}).length;
const failed=n(a.errors)+n(a.writeErrors);
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(a.startedAt).getTime())/1000)); }catch(e){}
const allFailed=n(a.called)>0&&n(a.errors)>=n(a.called)&&!n(a.written);
const lines=[
  '**QuickEnrich: '+n(a.companiesIn)+' companies asked in '+n(a.chunks)+' chunk'+(n(a.chunks)===1?'':'s')+', '+n(a.returned)+' people returned, '+n(a.built)+' new, '+n(a.updated)+' held filled, '+n(a.written)+' rows written**',
  '', '**Parent run:** '+(ctx.parentExecId||'?')+' (this row is the QuickEnrich lane of it)',
  '', '- **Vendor:** called '+n(a.called)+', returned '+n(a.returned)+', kept '+n(a.kept)+(n(a.credits)?', credits '+(Math.round(n(a.credits)*100)/100):'')+(n(a.errors)?', errors '+n(a.errors)+(a.firstError?' ('+a.firstError+')':''):''),
  '- **Merge:** '+n(a.built)+' new rows; '+n(a.updated)+' held rows filled ('+n(a.emailsAppended)+' emails appended); '+n(a.heldUnchanged)+' held unchanged; '+n(a.dupes)+' same-person merges; '+n(a.noKey)+' without a usable first name; '+n(a.fenced)+' LinkedIn URLs rejected by the name fence; '+n(a.dnc)+' on the DNC list',
  '- **Written (confirmed by Airtable):** '+n(a.written)+' ('+n(a.updatedWritten)+' updates of held rows)'+(n(a.writeErrors)?', '+n(a.writeErrors)+' refused':''),
  '- **Companies with at least one person after this lane:** '+covered
];
if(a.singleSelectSource) lines.push('- **Contact Source is a single select on this base:** only the first source per person was recorded');
if(a.skipped) lines.push('', '**Skipped ('+a.skipped+')**');
if((a.writeReasons||[]).length){ lines.push('', '**Write failures**'); for(const r of a.writeReasons) lines.push('- '+r); }
const log={ 'Execution ID':(ctx.parentExecId||String($execution.id))+'-quickenrich', 'Automation':'Enrich Contacts QuickEnrich', 'Status':allFailed?'Failed':(failed?'Succeeded with errors':'Succeeded'), 'Trigger':'event', 'Errors':failed, 'Run at':a.startedAt, 'Target':'People ('+(ctx.peopleTableId||'')+')', 'Records In':n(a.companiesIn), 'Records Out':n(a.written), 'Duration s':dur, 'Description':lines.join('\n'), 'Tally':JSON.stringify(Object.assign({}, a, { coveredDomains:covered })), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id };
if(ctx.clientRecId) log['Client']=[ctx.clientRecId];
return [{ json:log }];

// Lane Response: the last node, what the Rootflow receives from this lane: counters only.
const a=$getWorkflowStaticData('global').lane||{};
const covered=Object.keys(a.coveredDomains||{});
return [{ json:{ provider:'QuickEnrich', status:a.skipped?'skipped':((a.called&&a.errors>=a.called&&!a.written)?'error':'ok'), reason:a.skipped||a.firstError||'', chunks:a.chunks, called:a.called, returned:a.returned, kept:a.kept, credits:a.credits, errors:a.errors, built:a.built, updated:a.updated, dupes:a.dupes, fenced:a.fenced, emailsAppended:a.emailsAppended, dnc:a.dnc, written:a.written, writeErrors:a.writeErrors, singleSelectSource:!!a.singleSelectSource, coveredDomains:covered } }];
